"""Complete 20 original clinical-reasoning and bedside-interpretation questions."""
from create_exam_reasoning import rows,q,LR,BP,ref
from qbank_authoring import finalize
CM=ref('Clinical Methods: examination reference','https://www.ncbi.nlm.nih.gov/books/NBK201/')
FO=ref('IWGDF practical diabetic-foot guidelines: 2023','https://iwgdfguidelines.org/wp-content/uploads/2023/07/IWGDF-Guidelines-2023.pdf')

q('An automated BP device gives variable readings in a patient with an irregularly irregular pulse. Which response is appropriate?', 'Recognize possible device limitations and obtain repeated suitable manual measurements with rhythm assessment',[
 ('Average one reading and regard it as exact','Irregular rhythm and technique can cause variability.'),('Ignore the BP because no method can ever be useful in AF','Appropriate repeated measurement remains possible.'),('Assume the irregular pulse proves a device error rather than an arrhythmia','The rhythm itself needs assessment.')],
 'Match measurement technique to the physiology','**Beat-to-beat variation can challenge oscillometric measurement.**',['Use a validated method and adequate repeated observations.','Confirm the rhythm with an ECG when indicated.'],'**Assess the clinical state rather than one isolated number.**',['Do not delay support for a symptomatic unstable patient.','Document technique and variability.'],[['Rhythm','Irregular'],['BP','Repeat with suitable technique'],['Confirmation','ECG and clinical context']],[BP,ref('NICE hypertension measurement guidance','https://www.nice.org.uk/guidance/ng136/chapter/recommendations')],style='clinical_scenario')

q('Rinne testing shows air conduction greater than bone conduction in both ears, but the patient reports hearing loss. Which conclusion is correct?', 'Sensorineural hearing loss remains possible because a positive Rinne occurs in normal hearing and sensorineural loss',[
 ('The result excludes any hearing deficit','Rinne compares pathways rather than absolute hearing sensitivity.'),('The result proves bilateral conductive deafness','Conductive loss can reverse the relationship when sufficiently marked.'),('The result measures vestibular function','It is a hearing test.')],
 'A relative conduction test is not a complete audiogram','**Air greater than bone is the usual Rinne relationship.**',['Interpret with Weber, otoscopy and history.','Profound unilateral loss can create misleading cross-hearing effects.'],'**Arrange audiometry when hearing loss is suspected.**',['Sudden sensorineural loss requires urgent assessment.','Use an appropriate tuning fork and technique.'],[['Positive Rinne','Normal or sensorineural loss'],['Negative Rinne','Conductive pattern in context'],['Confirmation','Audiometry']],[CM])

q('Weber lateralizes to the left in a patient with a conductive hearing deficit on that side. Which interpretation fits?', 'A conductive deficit can lateralize Weber toward the affected ear',[
 ('Weber always lateralizes away from any impaired ear','The direction differs between conductive and sensorineural patterns.'),('This establishes a right conductive deficit','That would more typically lateralize toward the right.'),('The test identifies the exact middle-ear pathology','It does not distinguish all conductive causes.')],
 'Interpret lateralization with the type of loss','**Unilateral sensorineural loss generally lateralizes to the better ear, while conductive loss can lateralize to the affected ear.**',['Mixed losses and technical factors can complicate the pattern.','Rinne and otoscopy provide complementary information.'],'**Confirm clinically important loss with audiometry.**',['Assess sudden onset and red flags.','Do not diagnose a specific lesion from Weber alone.'],[['Conductive','Toward affected side'],['Sensorineural','Toward better side'],['Limit','Not exact cause']],[CM],style='clinical_scenario')

q('A diffusely enlarged thyroid has a bruit in a patient with tremor, tachycardia and eye findings. Which mechanism is suggested?', 'Increased thyroid vascularity in a thyrotoxic state such as Graves disease',[
 ('A bruit uniquely establishes thyroid carcinoma','It is not a cancer-specific sign.'),('The sound proves normal thyroid hormone levels','Functional assessment requires laboratory testing.'),('The sound is necessarily transmitted carotid stenosis','Transmission is a differential, but location and the full thyroid syndrome support thyroid vascularity.')],
 'A vascular sign complements the endocrine phenotype','**A hypervascular gland can generate an audible bruit.**',['Confirm the source and avoid confusing carotid transmission.','The absence of a bruit does not exclude Graves disease.'],'**Use thyroid function and etiological testing.**',['Assess cardiovascular severity and compressive symptoms.','Do not infer the exact hormone concentration from the bruit.'],[['Gland','Diffuse enlargement'],['Bruit','Vascularity clue'],['Diagnosis','Clinical plus biochemical/etiological assessment']],[CM],style='clinical_scenario')

q('Raising both arms causes facial congestion, neck-vein distension and dyspnea in a patient with a large goiter. Which interpretation is appropriate?', 'Thoracic-inlet obstruction is suggested by a positive Pemberton maneuver',[
 ('This directly proves thyroid malignancy','A benign substernal goiter can also compress structures.'),('The maneuver establishes a primary panic disorder','The reproducible vascular/respiratory findings require anatomical assessment.'),('The finding excludes airway compression','It raises concern for compressive physiology.')],
 'Position can reveal limited space at the thoracic inlet','**Arm elevation can worsen venous and airway compromise from a large retrosternal process.**',['Stop the maneuver when symptoms occur.','Other thoracic-inlet masses can produce similar effects.'],'**Assess compressive urgency and anatomy.**',['Use appropriate imaging and airway/surgical expertise.','Do not repeatedly provoke distress for demonstration.'],[['Trigger','Arm elevation'],['Response','Congestion/dyspnea'],['Concern','Thoracic-inlet compression']],[CM],style='clinical_scenario')

q('What is the principal purpose of the 10-g monofilament in a diabetic foot assessment?', 'Detect loss of protective pressure sensation associated with ulcer risk',[
 ('Measure arterial perfusion directly','Pulses, pressures and vascular tests assess perfusion.'),('Exclude every early small-fiber neuropathy','A normal result does not exclude all neuropathy.'),('Measure muscle power','This is a sensory rather than motor test.')],
 'Use the tool for the risk domain it measures','**Protective sensation is one component of foot-risk stratification.**',['Use standardized sites and technique, avoiding callus where instructed.','Complement with another sensory modality and vascular/structural assessment.'],'**Translate findings into prevention and follow-up.**',['Assess footwear, deformity, skin and prior ulcer history.','Teach daily inspection and prompt review of injury.'],[['Monofilament','Protective sensation'],['Vascular exam','Perfusion'],['Risk plan','Combined domains']],[FO])

q('A patient with diabetes and a foot ulcer has ABI 1.55. Which conclusion is appropriate?', 'Noncompressible calcified arteries may make ABI misleading; use toe pressures/TBI or other suitable vascular assessment',[
 ('The high ABI proves excellent perfusion','Medial calcification can prevent cuff compression.'),('Peripheral arterial disease is excluded permanently','A falsely high ABI can coexist with ischemia.'),('The value directly identifies a venous ulcer','ABI does not establish that etiology.')],
 'A number outside the reliable range is not reassurance','**Noncompressibility can overestimate ankle pressure.**',['Diabetes and CKD increase this concern.','Clinical ulcer/ischemia findings still matter.'],'**Use an appropriate alternative and specialist pathway.**',['Toe vessels may be more informative, though all tests have limits.','Assess infection and pressure-related injury concurrently.'],[['ABI >1.40','Possible noncompressibility'],['Risk','Diabetes/CKD'],['Alternative','Toe-based or other vascular testing']],[FO,ref('ACC/AHA lower-extremity PAD guideline: 2024','https://doi.org/10.1161/CIR.0000000000001251')],style='clinical_scenario')

q('Which statement about an Allen-type hand collateral-circulation test is most accurate?', 'It is a bedside assessment with limitations and does not guarantee absence of ischemic complications after arterial access',[
 ('A normal result guarantees no future hand ischemia','No bedside result provides that guarantee.'),('An abnormal result identifies the exact radial lesion without imaging','Further assessment may be needed.'),('It measures the absolute coronary perfusion pressure','It tests a different vascular territory.')],
 'A procedural safety test has a limited question','**Collateral hand flow depends on anatomy, vascular state and technique.**',['Protocols and the role of Doppler/other assessment vary.','Interpret the result with the procedure and overall vascular risk.'],'**Follow the appropriate access protocol and monitor afterward.**',['Do not use a reassuring result to ignore new pain, pallor or perfusion loss.','Avoid claiming the test perfectly predicts complications.'],[['Purpose','Hand collateral assessment'],['Limit','Imperfect predictive value'],['Safety','Protocol and post-procedure monitoring']],[CM])

q('Before an intimate examination, which approach is appropriate?', 'Explain the indication and steps, obtain consent, offer appropriate chaperone arrangements and respect the patient’s right to stop',[
 ('Assume hospital admission provides consent for every examination','Consent is examination-specific and requires communication.'),('Treat a chaperone as a substitute for consent','The roles are distinct.'),('Continue despite withdrawal of consent unless a separate lawful emergency basis applies','The patient’s wishes and applicable legal framework must be respected.')],
 'Examination quality includes dignity and control','**Clear explanation supports informed participation.**',['Privacy, exposure and communication needs matter.','Follow local professional and legal requirements for chaperones and documentation.'],'**Use the least intrusive examination that answers the clinical question.**',['Allow questions and pause when requested.','Document relevant consent and chaperone details.'],[['Consent','Specific and ongoing'],['Chaperone','Support/safeguard, not consent replacement'],['Technique','Dignity and minimum necessary exposure']],[ref('GMC intimate examination and chaperone guidance','https://www.gmc-uk.org/professional-standards/the-professional-standards/intimate-examinations-and-chaperones')])

q('A patient initially thought to have musculoskeletal chest pain later develops diaphoresis, hypotension and new ECG changes. Which reasoning response is appropriate?', 'Reopen the differential and urgently reassess the new high-risk evidence',[
 ('Preserve the original label because initial chest-wall tenderness excludes serious disease','Tenderness does not exclude every acute cardiovascular problem.'),('Interpret every new finding as confirmation of the first diagnosis','This is anchoring/confirmation bias.'),('Wait for the original analgesic plan to finish before reassessment','The new instability requires prompt action.')],
 'A working diagnosis must remain revisable','**New discordant evidence changes disease probability and urgency.**',['Clinical reasoning is iterative.','A reassuring early feature does not negate later objective deterioration.'],'**Stabilize and investigate the updated syndrome.**',['Communicate the change and revise the care plan.','Use a diagnostic time-out when the course no longer fits.'],[['Initial label','Provisional'],['New evidence','Updates probability'],['Action','Urgent reassessment']],[LR],style='clinical_scenario')

if __name__=='__main__':finalize('Clinical Examination',6,'Clinical Reasoning and Bedside Interpretation','exam-reasoning',rows,20)
